from collections import OrderedDict


class LRUCache:
    """LRU cache holding at most ``capacity`` keys (capacity >= 1).

    ``get(key)`` returns the stored value or ``None`` if absent, and counts
    as a use.  ``put(key, value)`` inserts or updates a key and counts as a
    use.  When an insertion would exceed the capacity, the least recently
    used key is evicted first.  ``len(cache)`` returns the number of keys.
    """

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)

    def __contains__(self, key):
        return key in self._data

    def __getitem__(self, key):
        value = self.get(key)
        if value is None and key not in self._data:
            raise KeyError(key)
        return value

    def __setitem__(self, key, value):
        self.put(key, value)

    def __delitem__(self, key):
        del self._data[key]

    def __iter__(self):
        return iter(self._data)

    def __repr__(self):
        return "LRUCache(capacity=%r, items=%r)" % (
            self.capacity,
            list(self._data.items()),
        )
"}

